"use client";

import { useState } from "react";
import { 
  MapPin, Phone, Mail, Clock, Calendar, 
  Send, MessageCircle, Instagram, Facebook, Globe, Search 
} from "lucide-react";

export default function ContactPage() {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    service: "",
    preferredDate: "",
    preferredTime: "",
    message: ""
  });

  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState("");
  const [error, setError] = useState("");

  // ✅ Fixed environment variable access
  const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000";
  
  const services = [
    "Tarot Reading",
    "Numerology Consultation", 
    "Angel Healing",
    "Vastu Consultation",
    "Astrology Reading",
    "Spells"
  ];

  const timeSlots = [
    "10:00 AM", "11:00 AM", "12:00 PM", 
    "2:00 PM", "3:00 PM", "4:00 PM", 
    "5:00 PM", "6:00 PM"
  ];

  const handleSubmit = async (e) => {
    e.preventDefault();

    // ✅ Validation
    if (!formData.name || !formData.email || !formData.phone || !formData.service) {
      setError("Please fill in all required fields: Name, Email, Phone, and Service.");
      return;
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(formData.email)) {
      setError("Please enter a valid email address.");
      return;
    }
    const phoneRegex = /^[0-9]{10}$/;
    if (!phoneRegex.test(formData.phone.replace(/\D/g, ""))) {
      setError("Please enter a valid 10-digit phone number.");
      return;
    }

    setLoading(true);
    setError("");
    setSuccess("");

    try {
      // ✅ Fixed API URL string interpolation
      const res = await fetch(`${API_BASE_URL}/api/appointments`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          fullName: formData.name,
          email: formData.email,
          phone: formData.phone,
          service: formData.service,
          date: formData.preferredDate,
          time: formData.preferredTime,
          message: formData.message
        })
      });

      if (!res.ok) throw new Error("Failed to book appointment");

      setSuccess("✅ Appointment booked successfully! We will contact you soon.");
      setFormData({
        name: "",
        email: "",
        phone: "",
        service: "",
        preferredDate: "",
        preferredTime: "",
        message: ""
      });
    } catch (err) {
      setError("❌ Something went wrong. Please try again later.");
      console.error("Appointment booking error:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (field, value) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  return (
    <div
      className="relative min-h-screen py-20 text-[#FFD700] overflow-hidden bg-cover bg-center"
      style={{ backgroundImage: "url('/assets/bg.png')" }}
    >
      <div className="relative container mx-auto px-4">
        {/* Header */}
        <section className="text-center mb-16 relative z-10">
          <h1 className="text-5xl font-serif font-bold mb-6 bg-gradient-to-r from-yellow-300 via-yellow-400 to-orange-400 text-transparent bg-clip-text">
            Book Your Session
          </h1>
          <p className="text-xl text-yellow-100/90 max-w-3xl mx-auto">
            Take the first step on your spiritual journey. Schedule a consultation 
            and discover the divine guidance that awaits you.
          </p>
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 relative z-10">
          {/* Contact Form */}
          <div className="bg-[#3b0022] text-[rgb(255,237,137)] rounded-2xl shadow-lg p-6 border border-yellow-100/20">
            <h2 className="text-2xl font-semibold flex items-center mb-6">
              <Calendar className="h-6 w-6 mr-2 text-yellow-200" />
              Schedule Appointment
            </h2>

            {success && <p className="text-green-400 mb-4">{success}</p>}
            {error && <p className="text-red-400 mb-4">{error}</p>}

            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Name + Email */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input
                  type="text"
                  placeholder="Full Name *"
                  value={formData.name}
                  onChange={(e) => handleInputChange("name", e.target.value)}
                  className="w-full border border-yellow-100/20 bg-[#3b0022] rounded-md p-2 text-yellow-200 placeholder-yellow-200/70"
                  required
                />
                <input
                  type="email"
                  placeholder="Email Address *"
                  value={formData.email}
                  onChange={(e) => handleInputChange("email", e.target.value)}
                  className="w-full border border-yellow-100/20 bg-[#3b0022] rounded-md p-2 text-yellow-200 placeholder-yellow-200/70"
                  required
                />
              </div>

              {/* Phone */}
              <input
                type="tel"
                placeholder="Phone Number *"
                value={formData.phone}
                onChange={(e) => handleInputChange("phone", e.target.value)}
                className="w-full border border-yellow-100/20 bg-[#3b0022] rounded-md p-2 text-yellow-200 placeholder-yellow-200/70"
                required
              />

              {/* Service */}
              <select
                value={formData.service}
                onChange={(e) => handleInputChange("service", e.target.value)}
                className="w-full border border-yellow-100/20 bg-[#3b0022] rounded-md p-2 text-yellow-200"
                required
              >
                <option value="">Select a service *</option>
                {services.map((service) => (
                  <option key={service} value={service}>{service}</option>
                ))}
              </select>

              {/* Date + Time */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input
                  type="date"
                  value={formData.preferredDate}
                  onChange={(e) => handleInputChange("preferredDate", e.target.value)}
                  min={new Date().toISOString().split("T")[0]}
                  className="w-full border border-yellow-100/20 bg-[#3b0022] rounded-md p-2 text-yellow-200"
                />
                <select
                  value={formData.preferredTime}
                  onChange={(e) => handleInputChange("preferredTime", e.target.value)}
                  className="w-full border border-yellow-100/20 bg-[#3b0022] rounded-md p-2 text-yellow-200"
                >
                  <option value="">Select time</option>
                  {timeSlots.map((time) => (
                    <option key={time} value={time}>{time}</option>
                  ))}
                </select>
              </div>

              {/* Message */}
              <textarea
                placeholder="Additional Message (optional)"
                value={formData.message}
                onChange={(e) => handleInputChange("message", e.target.value)}
                className="w-full border border-yellow-100/20 bg-[#3b0022] rounded-md p-2 min-h-[100px] text-yellow-200 placeholder-yellow-200/70"
              />

              {/* Submit */}
              <button
                type="submit"
                disabled={loading}
                className="w-full flex items-center justify-center gap-2 bg-[#FFD700] text-[#2a0015] font-bold py-3 px-6 rounded-xl hover:-translate-y-1 hover:bg-[#FFE066] transition-transform duration-300 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <Send className="inline h-4 w-4 mr-2" />
                {loading ? "Booking..." : "Send Appointment Request"}
              </button>
            </form>
          </div>

          {/* Right side (Contact Info, Socials, Expectations) */}
          <div className="space-y-8 text-[rgb(255,237,137)]">
            {/* Contact Info */}
            <div className="bg-[#3b0022] rounded-2xl shadow-lg p-6 border border-yellow-100/20 hover:-translate-y-1 hover:shadow-yellow-400/20 transition-transform duration-300">
              <h2 className="text-2xl mb-4 font-semibold">Contact Information</h2>
              <div className="space-y-4">
                <div className="flex items-start space-x-3">
                  <MapPin className="h-6 w-6 mt-1 text-yellow-300" />
                  <div>
                    <h3 className="font-semibold">Location</h3>
                    <p>Kandivali West<br />Mumbai, Maharashtra<br />India</p>
                    <a 
                      href="https://maps.google.com/?q=Kandivali+West+Mumbai"
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center mt-2 underline text-yellow-200"
                    >
                      <Search className="h-4 w-4 mr-1" /> View on Maps
                    </a>
                  </div>
                </div>
                <div className="flex items-start space-x-3">
                  <Phone className="h-6 w-6 mt-1 text-yellow-300" />
                  <a href="tel:+919876543210" className="hover:underline text-yellow-200">
                    +91 98765 43210
                  </a>
                </div>
                <div className="flex items-start space-x-3">
                  <Mail className="h-6 w-6 mt-1 text-yellow-300" />
                  <a href="mailto:contact@divinemiracle.com" className="hover:underline text-yellow-200">
                    contact@divinemiracle.com
                  </a>
                </div>
                <div className="flex items-start space-x-3">
                  <Clock className="h-6 w-6 mt-1 text-yellow-300" />
                  <p>
                    Mon-Sat: 10:00 AM - 8:00 PM<br />
                    Sun: 11:00 AM - 6:00 PM
                  </p>
                </div>
              </div>
            </div>

            {/* Social Links */}
            <div className="bg-[#3b0022] rounded-2xl shadow-lg p-6 border border-yellow-100/20 hover:-translate-y-1 hover:shadow-yellow-400/20 transition-transform duration-300">
              <h2 className="text-xl font-semibold mb-4">Connect With Us</h2>
              <div className="grid grid-cols-2 gap-4">
                <a href="https://wa.me/919876543210" target="_blank" rel="noopener noreferrer" className="flex items-center space-x-2 p-3 border border-yellow-100/20 rounded-lg hover:shadow-yellow-400/20 hover:-translate-y-0.5 transition duration-300">
                  <MessageCircle className="h-5 w-5 text-green-500" />
                  <span>WhatsApp</span>
                </a>
                <a href="https://instagram.com/divinemiracle.in" target="_blank" rel="noopener noreferrer" className="flex items-center space-x-2 p-3 border border-yellow-100/20 rounded-lg hover:shadow-yellow-400/20 hover:-translate-y-0.5 transition duration-300">
                  <Instagram className="h-5 w-5 text-pink-700" />
                  <span>Instagram</span>
                </a>
                <a href="https://facebook.com/divinemiracle.mumbai" target="_blank" rel="noopener noreferrer" className="flex items-center space-x-2 p-3 border border-yellow-100/20 rounded-lg hover:shadow-yellow-400/20 hover:-translate-y-0.5 transition duration-300">
                  <Facebook className="h-5 w-5 text-blue-400" />
                  <span>Facebook</span>
                </a>
                <a href="https://g.co/kgs/divinemiracle" target="_blank" rel="noopener noreferrer" className="flex items-center space-x-2 p-3 border border-yellow-100/20 rounded-lg hover:shadow-yellow-400/20 hover:-translate-y-0.5 transition duration-300">
                  <Globe className="h-5 w-5 text-blue-500" />
                  <span>Google</span>
                </a>
              </div>
            </div>

            {/* Expectations */}
            <div className="bg-[#3b0022] rounded-2xl shadow-lg p-6 border border-yellow-100/20 hover:-translate-y-1 hover:shadow-yellow-400/20 transition-transform duration-300">
              <h2 className="text-xl font-semibold mb-4">What to Expect</h2>
              <ul className="list-disc pl-5 space-y-2">
                <li>Confirmation call within 24 hours</li>
                <li>Prepare your questions beforehand</li>
                <li>Sessions conducted in a peaceful environment</li>
                <li>Recordings available upon request</li>
                <li>Follow-up guidance included</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}